import genesis as gs

def main():
    gs.init()

    scene = gs.Scene(
        viewer_options=gs.options.ViewerOptions(
            camera_pos=(3.5, 0.0, 2.5),
            camera_lookat=(0.0, 0.0, 0.5),
        ),
        show_viewer=True,
    )

    # flat ground
    plane = scene.add_entity(
        morph=gs.options.morphs.Plane(),
    )

    # red rigid sphere
    sphere = scene.add_entity(
        morph=gs.options.morphs.Sphere(
            pos=(0.0, 0.0, 2.0),
            radius=0.2,
        ),
        material=gs.materials.Rigid(),
        surface=gs.options.surfaces.Rough(
            texture=gs.options.textures.ColorTexture(color=(1.0, 0.0, 0.0, 1.0)),
        ),
    )

    scene.build()

    for _ in range(200):
        scene.step()

if __name__ == "__main__":
    main()

import genesis as gs


def main():
    gs.init()

    scene = gs.Scene(
        sim_options=gs.options.SimOptions(
            gravity=(0.0, 0.0, 0.0),
        ),
        viewer_options=gs.options.ViewerOptions(
            camera_pos=(3.0, 3.0, 2.0),
            camera_lookat=(0.0, 0.0, 0.5),
        ),
        show_viewer=True,
    )

    box = scene.add_entity(
        gs.morphs.Box(
            pos=(0.0, 0.0, 0.5),
            size=(0.3, 0.3, 0.3),
        ),
        material=gs.materials.Rigid(),
    )

    scene.build()

    for _ in range(500):
        scene.step()


if __name__ == "__main__":
    main()
